// Arma el mensaje para el asistente. Si hay crítica previa del controlador, la agrega (ruta Corregir).
const d = $input.first().json;
let p = '';
if (d.resumen_previo) p += 'RESUMEN DE LA CONVERSACIÓN PREVIA (solo para entender el contexto; NO es fuente de datos):
' + d.resumen_previo + '

';
p += 'CONSULTA DEL PACIENTE:
' + d.mensaje;
if (d.critica_previa) {
  p += '

TU RESPUESTA ANTERIOR:
' + d.respuesta_previa + '

CRÍTICA DEL CONTROLADOR:
' + d.critica_previa +
       '

Corregí tu respuesta siguiendo la crítica y volvé a consultar la herramienta si hace falta.';
}
return [{ json: { ...d, prompt_agente: p } }];

// Junta lo que el asistente recuperó del manual y verifica las citas contra los metadatos reales.
const out = $input.first().json;
const steps = Array.isArray(out.intermediateSteps) ? out.intermediateSteps : [];
const obs = steps.map(s => (typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation || ''))).filter(Boolean);
const contexto = obs.join('\n---\n').slice(0, 7000);
const usoRag = steps.length > 0 && contexto.length > 0;

const paginas = new Set();
for (const m of contexto.matchAll(/\\?"pageNumber\\?"\s*:\s*(\d+)/g)) paginas.add(m[1]);

let respuesta = String(out.output || '').trim();
if (!usoRag) {
  // Sin consulta al manual no se permite ninguna respuesta con datos.
  respuesta = 'No sé: ese dato no figura en la documentación disponible. Una persona del equipo lo va a revisar.';
}
const noSe = /\bno s[eé](?![a-záéíóúñ])/i.test(respuesta);
const lineasFuente = [...respuesta.matchAll(/Fuente:\s*([^\n]+)/gi)].map(m => m[1].trim());
const citadas = [];
for (const l of lineasFuente) for (const m of l.matchAll(/p[áa]gina\s*(\d+)/gi)) citadas.push(m[1]);
const citaValida = noSe ? true : (citadas.length > 0 && citadas.every(p => paginas.has(p)));

return [{ json: {
  status: 'ok',
  respuesta_agente: respuesta,
  contexto_recuperado: contexto,
  fuentes_citadas: lineasFuente,
  paginas_recuperadas: [...paginas],
  cita_valida: citaValida,
  respondio_no_se: noSe,
  uso_rag: usoRag
} }];
